-- Rollback for 20270255 (CR-343) and 20270256 (CR-344). Restores the open policies exactly as they stood on the live project before the change, then removes what the migration added.
-- The status constraint goes back to its three values only if no pending or declined row exists (a row that uses the new statuses would be refused; remove or convert it first).
do $r$ begin if exists (select 1 from public.mentor_assignments where status in ('pending','declined')) then raise exception 'mentor_assignments holds pending or declined rows; convert them before rolling back'; end if; end $r$;
alter table public.mentor_assignments drop constraint if exists mentor_assignments_status_check;
alter table public.mentor_assignments add constraint mentor_assignments_status_check check (status = any (array['active','completed','transferred']));


